import{_ as t,o as e,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const r="/assets/logistics-viewer.a273e149.svg",s="/assets/part-batch-states.cc9f257e.svg",n="/assets/declare-materials.a4f49990.svg",i="/assets/kit-labels.872f0845.svg",y=JSON.parse('{"title":"Logistics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logistics/index.md","filePath":"guide/logistics/index.md","lastUpdated":1790346505000}'),h={name:"guide/logistics/index.md"},l=o('<h1 id="logistics" tabindex="-1">Logistics <a class="header-anchor" href="#logistics" aria-label="Permalink to &quot;Logistics&quot;">​</a></h1><p>The Logistics view provides an overview of material requirements across your constructibles, helping you track which parts are available and which still need to be prepared.</p><nav class="table-of-contents"><ul><li><a href="#layout">Layout</a></li><li><a href="#material-tracking">Material Tracking</a></li><li><a href="#sorting">Sorting</a></li><li><a href="#filtering">Filtering</a></li><li><a href="#columns">Columns</a></li><li><a href="#selecting-from-a-report">Selecting from a Report</a></li><li><a href="#part-batches">Part Batches</a><ul><li><a href="#declaring-the-material">Declaring the material</a></li><li><a href="#where-the-batches-live">Where the batches live</a></li></ul></li><li><a href="#marking-parts-ready">Marking Parts Ready</a></li><li><a href="#kitted-parts">Kitted Parts</a><ul><li><a href="#what-production-sees">What production sees</a></li><li><a href="#where-the-count-comes-from">Where the count comes from</a></li><li><a href="#choosing-who-decides">Choosing who decides</a></li><li><a href="#starting-a-panel-that-is-not-ready">Starting a panel that is not ready</a></li><li><a href="#in-the-constructibles-list">In the Constructibles list</a></li><li><a href="#on-the-dashboard">On the dashboard</a></li></ul></li><li><a href="#part-drawings">Part Drawings</a></li><li><a href="#connection-to-other-features">Connection to Other Features</a></li></ul></nav><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The screen is laid out like the panel viewer:</p><ul><li><strong>The table</strong>, with the branch and size pickers above it.</li><li><strong>The toolbar</strong>, a column beside it, holding the part batch, the search, the sorting, <em>Hide completed</em>, the columns, the button to mark all parts ready and every message the view has to give you.</li><li><strong>The part panel</strong>, showing the drawing and the properties of the part you picked in the table.</li></ul><p>The top button in the toolbar, <strong>Part data</strong>, opens and closes the part panel: with it closed the table takes the whole width. The choice is remembered on the device.</p><p>On a phone the toolbar becomes a bar at the bottom of the screen; press the chevron and it opens upwards.</p><p><img src="'+r+'" alt="The logistics viewer with a part batch running"></p><ol><li>The panels of the project, ticked to put their parts in the table. With kit tracking on, each one shows how many of its parts are ready.</li><li>The branch and the size. The table shows one size at a time.</li><li>A zone header, with its own progress. See <a href="#sorting">Sorting</a>.</li><li><strong>Ready Parts</strong>: type the number or use <code>−</code> and <code>+</code>.</li><li>The totals of the list.</li><li><strong>Part data</strong> opens and closes the part panel.</li><li>The part batch block. See <a href="#part-batches">Part Batches</a>.</li><li>Search, sorting, <em>Hide completed</em> and the columns.</li><li>The drawings of the part you picked, and its 3D view.</li></ol><h2 id="material-tracking" tabindex="-1">Material Tracking <a class="header-anchor" href="#material-tracking" aria-label="Permalink to &quot;Material Tracking&quot;">​</a></h2><p>The table shows one row per part to prepare, with these columns:</p><table><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Zone</strong></td><td>The structural area in the design where this part is used. Shown in the flat list only: when the table is grouped by zone, each zone is a header row instead. Projects without zones don&#39;t show it.</td></tr><tr><td><strong>Reference</strong></td><td>The part reference. Shaped parts (not a straight cut) carry an extra icon in front of it.</td></tr><tr><td><strong>Material</strong></td><td>Material name.</td></tr><tr><td><strong>Finish</strong> / <strong>Comment</strong></td><td>Only shown when some part in the list has one, because they split otherwise identical rows.</td></tr><tr><td><strong>Width</strong></td><td>Plates only.</td></tr><tr><td><strong>Length</strong></td><td>Length of the part.</td></tr><tr><td><strong>#</strong></td><td>Total number of this part needed across the selected constructibles.</td></tr><tr><td><strong>Counts by Constructible</strong></td><td>How many each assembly or module needs. The first two are shown as chips (grey: not started, orange: in production, green: ready), with the rest behind a <code>+N</code> chip.</td></tr><tr><td><strong>Ready Parts</strong></td><td>How many have been prepared. This column stays pinned to the right edge.</td></tr></tbody></table><p>Rows whose parts are all ready are tinted green. A totals line at the bottom sums up rows, parts, ready parts, pending parts and the overall percentage.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Click a column header to sort by it. Each header you click is added to the sort after the ones already active: click it again to reverse it, and a third time to take it out. Zone and reference sort naturally, so <code>Z2</code> comes before <code>Z10</code> and reference <code>9</code> before <code>114</code>.</p><p>The <strong>Sort</strong> menu has four ready-made orders:</p><ul><li><strong>Longest first</strong> — the default, for cutting at the saw.</li><li><strong>Reference A-Z</strong> — to find a specific part.</li><li><strong>Pending first</strong> — to see what is still missing.</li><li><strong>Zone then reference</strong> — the kitting order.</li></ul><p>The same menu switches between <strong>Group by zone</strong>, where each zone is a header row with its own progress and the sorting applies inside it, and <strong>Flat list</strong>, where the order applies to the whole table. Projects without zones always use the flat list.</p><p>Your sorting, grouping, density and hidden columns are remembered on the device.</p><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><ul><li><strong>Branch</strong> — One button per branch in the selection (for example <code>timber</code> or <code>plate</code>). If your production line is a logistics line, only the branches of that line are offered.</li><li><strong>Size</strong> — Filter to a specific material size. One at a time: this is a production view, and a run at the saw is one size. When the sizes do not fit in one row they move into a dropdown. The size cannot be changed while a part batch is running or paused.</li><li><strong>Search</strong> — Filter the table by reference, zone, material, finish or comment.</li><li><strong>Hide completed</strong> — Leave only the rows with parts still pending.</li></ul><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The table only shows columns that say something different on each row. When every part in the list is the same material — which is what usually happens, since you pick a branch and a size before the list appears — the <strong>Material</strong> column is dropped and the material is written once in the toolbar, as a chip. The same goes for <strong>Finish</strong>, <strong>Comment</strong> and, on plates, <strong>Width</strong>.</p><p>The <strong>Columns</strong> menu turns <strong>Material</strong>, <strong>Finish</strong>, <strong>Comment</strong> and <strong>Counts by Constructible</strong> on and off, and sets the row density: <strong>Spacious</strong>, <strong>Comfortable</strong> or <strong>Compact</strong>. Spacious gives bigger <code>−</code> and <code>+</code> buttons for touch screens.</p><h2 id="selecting-from-a-report" tabindex="-1">Selecting from a Report <a class="header-anchor" href="#selecting-from-a-report" aria-label="Permalink to &quot;Selecting from a Report&quot;">​</a></h2><p>Above the panel list in the left menu, <strong>Select from report</strong> takes the selection of a report and loads it into the menu: pick one and the assemblies and modules it has selected are ticked for you.</p><p>Only reports marked as <strong>final</strong> are listed — a document still being worked on is not something to produce against — so the button is not there at all when the project has no final report yet.</p><h2 id="part-batches" tabindex="-1">Part Batches <a class="header-anchor" href="#part-batches" aria-label="Permalink to &quot;Part Batches&quot;">​</a></h2><p>A part batch is a run of work: the parts you are about to cut, from the moment you start until you finish and put the leftover material back.</p><p>The <strong>batch block</strong> sits in the toolbar, just below <strong>Part data</strong>:</p><ol><li><strong>Pick a batch</strong> in the <strong>Part Batch</strong> selector, if somebody prepared one for you in the parts list. Picking it makes the table show that batch and nothing else.</li><li><strong>Start production</strong> — with no batch picked, this creates one out of what is on the table (your selection, the branch and the size) and starts it. <strong>Start batch</strong> does the same for the batch you picked. Either way, who started it and when are recorded, and from then on the counters work. Before that, the counters are locked and <strong>All ready</strong> is not there. If those parts are already in a batch that has been started, that batch is opened and resumed instead of a second one being started over the same work — one press, whether it was left running or paused.</li><li><strong>While it runs</strong>, the block shows the progress of the whole batch, when it started, who started it and the time worked. <strong>Pause</strong> stops the clock; the counters lock again until you press <strong>Resume</strong>.</li><li><strong>Finish batch</strong> — or marking the last pending part — opens the form to declare the material. A batch can only be closed once every part in it is marked ready.</li></ol><p><img src="'+s+'" alt="The part batch block in its four states"></p><ol><li>Nothing picked: <strong>Start production</strong> makes a batch out of what is on the table.</li><li>A batch prepared in the parts list, not started yet: <strong>Start batch</strong>.</li><li>Running: progress, start time, who started it and the time worked.</li><li>Paused: the counters are locked until you press <strong>Resume</strong>.</li></ol><p>Several batches can run at the same time, and you can switch between them whenever you want. If you leave a running batch — by picking another one, by changing the selection, or by navigating away — you are asked whether to pause the one you are leaving, exactly like leaving a panel with an open checklist in the viewer.</p><p>Nothing happens automatically overnight: a batch stays open until somebody pauses or finishes it.</p><h3 id="declaring-the-material" tabindex="-1">Declaring the material <a class="header-anchor" href="#declaring-the-material" aria-label="Permalink to &quot;Declaring the material&quot;">​</a></h3><p>The closing form, <strong>Declare materials</strong>, has one section per size in the batch, plus one for <strong>Accessories and other materials</strong>. Each section has two lists:</p><ul><li><strong>Taken from stock</strong> — what you took for this batch.</li><li><strong>Material returned to stock</strong> — what you put back.</li></ul><p>Press <strong>Add line</strong> to add a line. What a line asks for depends on the material: a length and a number of pieces for timber, a width, a height and a number of pieces for sheets, and a description and a number of pieces for anything else. A <strong>Notes</strong> field sits at the bottom.</p><p>Press <strong>Confirm and close batch</strong> to save and close. <strong>Nothing to declare</strong> closes the batch without any lines; it is a normal outcome and needs no explanation. If some parts are still pending, the form says so and both buttons stay off.</p><p>The employees currently working are shown at the top of the form, and the declaration is filed under them.</p><p>Produuz.it does not keep stock levels: this declaration is sent onwards, to the system that does.</p><p><img src="'+n+'" alt="The Declare materials form"></p><ol><li>The employees the declaration is filed under.</li><li>One section per size in the batch.</li><li>What you took and what you put back, side by side.</li><li><strong>Nothing to declare</strong> closes the batch with no lines.</li></ol><h3 id="where-the-batches-live" tabindex="-1">Where the batches live <a class="header-anchor" href="#where-the-batches-live" aria-label="Permalink to &quot;Where the batches live&quot;">​</a></h3><p><strong>Part batches</strong> lists them all: status, production line, project, progress, start, finish, time worked and who ran them, with a search and filters by status and production line. Clicking the name opens a panel on the right with the batch in full — its parts, its work sessions and the material declared — and the buttons to open it in the logistics view, pause or resume it, finish it and reopen it.</p><p>The view is in two places: in the <strong>company menu</strong>, where it lists every batch of the company, and in the <strong>project menu</strong>, where it lists only the batches of that project and drops the project column. Switching between All projects and a project keeps you on the list.</p><p>The <strong>production line</strong> is changed from that panel. It is the only field of a batch you can edit there, and it is saved as soon as you pick it.</p><p>Batches can also be composed by hand from the <strong>Parts list</strong>, by selecting parts and assigning them to a batch. That is the place to build a batch that mixes several sizes: the logistics view always works on one size at a time.</p><h2 id="marking-parts-ready" tabindex="-1">Marking Parts Ready <a class="header-anchor" href="#marking-parts-ready" aria-label="Permalink to &quot;Marking Parts Ready&quot;">​</a></h2><p>You can update the &quot;ready parts&quot; count for each material to track preparation progress:</p><ul><li>Click on the number to type it, or use the <code>−</code> and <code>+</code> buttons.</li><li>Use the <strong>All ready</strong> button in the batch block, just above <em>Finish batch</em>, to mark every part of the running batch as ready. It asks for confirmation first, and the dialog says that it marks the whole batch, including rows the search or <em>Hide completed</em> keeps out of view.</li></ul><h2 id="kitted-parts" tabindex="-1">Kitted Parts <a class="header-anchor" href="#kitted-parts" aria-label="Permalink to &quot;Kitted Parts&quot;">​</a></h2><p>A <strong>kit</strong> is everything a panel is built from. While its parts are still being cut, the panel cannot be assembled, and the production list says so.</p><h3 id="what-production-sees" tabindex="-1">What production sees <a class="header-anchor" href="#what-production-sees" aria-label="Permalink to &quot;What production sees&quot;">​</a></h3><p>On the panel list in the viewer, each panel carries one label:</p><table><thead><tr><th>Label</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>13 parts left</strong></td><td>still being cut. Grey while nothing has been cut yet, orange once cutting has started</td></tr><tr><td><strong>Kitted parts</strong></td><td>every part is ready (blue) — this panel can be built</td></tr><tr><td><em>(station marks)</em></td><td>work has started; the station marks carry the row from here</td></tr><tr><td><strong>Ready</strong></td><td>the panel is built (green)</td></tr></tbody></table><p>There is only ever one label. A panel with no parts recorded shows none, because there is nothing to report about a kit that does not exist. If a panel is started while parts are still missing, the count stays on the row in red.</p><p><img src="'+i+'" alt="Kit labels on the viewer list, and the Kit column"></p><ol><li>Nothing cut yet: grey.</li><li>Cutting has started: orange.</li><li>Every part is ready: <strong>Kitted parts</strong>.</li><li>Started with parts missing: the count turns red, followed by the station marks.</li><li>Built: <strong>Ready</strong>.</li><li>The <strong>Kit</strong> column of the Constructibles list. See <a href="#in-the-constructibles-list">In the Constructibles list</a>.</li></ol><h3 id="where-the-count-comes-from" tabindex="-1">Where the count comes from <a class="header-anchor" href="#where-the-count-comes-from" aria-label="Permalink to &quot;Where the count comes from&quot;">​</a></h3><p>A panel is kitted when <strong>all of its parts are marked ready</strong> in the logistics table. Parts that were replaced by a newer revision do not count — they are no longer part of the panel.</p><p>A <strong>module</strong> is kitted when every panel it contains has been <strong>built</strong>, and its own loose parts are ready. A module cannot be assembled until its panels physically exist, so a panel that merely has a complete kit is not enough.</p><h3 id="choosing-who-decides" tabindex="-1">Choosing who decides <a class="header-anchor" href="#choosing-who-decides" aria-label="Permalink to &quot;Choosing who decides&quot;">​</a></h3><p>In <strong>Company settings</strong>, press <strong>Settings</strong>: under <em>Company Workflow Settings</em>, the <strong>Kitted parts</strong> field has three options. Only company admins see the button.</p><table><thead><tr><th>Option</th><th>Who decides</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td>nobody. Nothing about kits is shown anywhere</td></tr><tr><td><strong>Manual</strong></td><td>the logistics operator marks a panel kitted by hand</td></tr><tr><td><strong>Automatic</strong> <em>(recommended)</em></td><td>the ready counts decide, on their own</td></tr></tbody></table><p>With <strong>Manual</strong> or <strong>Automatic</strong>, every panel in the logistics menu shows its kit progress as a fraction, such as <code>12/25</code>.</p><p>On <strong>Manual</strong>, you also get three ways to mark a kit:</p><ul><li>when every part of a panel you have selected becomes ready, a message in the toolbar names those panels, with a <strong>Mark kitted</strong> button;</li><li>a tick beside each panel in the logistics menu marks that one panel;</li><li>with panels ticked in the menu, a <strong>Mark kitted</strong> button above the list marks all of them after a confirmation.</li></ul><p>Use the last two when you know the kit is fine even though the counts disagree — an offcut used, a part cut outside the flow.</p><p>Marking a kit by hand never changes a panel&#39;s production status.</p><h3 id="starting-a-panel-that-is-not-ready" tabindex="-1">Starting a panel that is not ready <a class="header-anchor" href="#starting-a-panel-that-is-not-ready" aria-label="Permalink to &quot;Starting a panel that is not ready&quot;">​</a></h3><p>If you start a panel whose parts are not all cut, the viewer says so and tells you how many are missing. <strong>You can always carry on</strong> with <strong>Start anyway</strong>, or press <strong>Cancel</strong>. It is a warning, not a block. It appears once, when the panel is started, and not again when you move to the next station.</p><h3 id="in-the-constructibles-list" tabindex="-1">In the Constructibles list <a class="header-anchor" href="#in-the-constructibles-list" aria-label="Permalink to &quot;In the Constructibles list&quot;">​</a></h3><p>When kit tracking is on, the Constructibles list has a <strong>Kit</strong> column showing the same thing as a fraction — <code>12/25</code> (orange once cutting has started), <code>✓ 25/25</code> (green), or <code>—</code> when the panel has no parts. It sorts, so you can put the panels closest to ready at the top.</p><h3 id="on-the-dashboard" tabindex="-1">On the dashboard <a class="header-anchor" href="#on-the-dashboard" aria-label="Permalink to &quot;On the dashboard&quot;">​</a></h3><p><strong>Ready to build</strong> shows everything still to be built, per production line, split into what can be built now, what is partly cut, what has not been cut yet, and what has no parts recorded at all. The big number on top is what your factory could start today.</p><p>It sits next to <strong>Active backlog</strong>, which answers a different question: that one says where your panels are in production, this one says whether their material is there. A line with forty panels waiting and five kits complete is short of material.</p><h2 id="part-drawings" tabindex="-1">Part Drawings <a class="header-anchor" href="#part-drawings" aria-label="Permalink to &quot;Part Drawings&quot;">​</a></h2><p>When a part is selected, the right panel shows its drawings — combined, front, top, left and section views — for quick reference on the workshop floor.</p><p>Only views that show real features (cutouts, holes, bevels, non-rectangular profiles) are produced. If a particular view would just be a plain rectangle, it&#39;s skipped — the dimensions in the table already convey that. A part with no features at all gets no drawings.</p><p>For wood parts that aren&#39;t straight prisms (parts with cutouts, bevels or mitres), an extra <strong>3d</strong> button appears in front of the drawing view buttons. Clicking it opens the isolated part in an interactive 3D viewer, so any feature that&#39;s hard to read on a 2D drawing can be inspected directly. The button only shows up when this 3D model is available.</p><h2 id="connection-to-other-features" tabindex="-1">Connection to Other Features <a class="header-anchor" href="#connection-to-other-features" aria-label="Permalink to &quot;Connection to Other Features&quot;">​</a></h2><ul><li>Material requirements are derived from the designs and their BoM data.</li><li>The <a href="/guide/logistics/delivery/">Delivery &amp; Racks</a> feature uses the logistics data to plan how completed assemblies are loaded for transport.</li><li><a href="/guide/reports/">Reports</a> can generate Bills of Materials for ordering the materials tracked here.</li></ul>',85),d=[l];function c(p,g,u,m,b,f){return e(),a("div",null,d)}const k=t(h,[["render",c]]);export{y as __pageData,k as default};
